UPDATE cached_production_lines
SET display_order = CASE id
    WHEN '32000000-0000-4000-8000-000000000001' THEN 1
    WHEN '32000000-0000-4000-8000-000000000002' THEN 2
    WHEN '32000000-0000-4000-8000-000000000003' THEN 3
    WHEN '32000000-0000-4000-8000-000000000004' THEN 4
    ELSE display_order
END
WHERE id IN (
    '32000000-0000-4000-8000-000000000001',
    '32000000-0000-4000-8000-000000000002',
    '32000000-0000-4000-8000-000000000003',
    '32000000-0000-4000-8000-000000000004'
);
